  const double f_4 = pdf_field->getF(&pdf_xyz0, uint_t{4u});
  const double f_5 = pdf_field->getF(&pdf_xyz0, uint_t{5u});
  const double f_6 = pdf_field->getF(&pdf_xyz0, uint_t{6u});
